示。
// 复 数 的 结 构 类 型 定 义
typedef struct
{
float a;
float b;
} cnum ;
// 全 局 变 量
cnum x, y, z;
// 计 算 两 个 复 数 之 和
cnum add ( cnum p, cnum q)
{
cnum s;
s.a = p.a + q.a;
s.b = p.b + q.b;
return s;
}
thread1
{
cnum w;
w = add (x, y);
...
}
thread2
{
cnum w;
w = add (y, z);
...
}
thread3
{
cnum w;

w.b = 2;
z = add (z, w);
y = add (y, w);
...
}
